            const config = {
                cloudUrl,
                cloudApiKey,
                cloudSyncId,
                cloudAccessCode
            };

            const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
